package africa.tesa.bloodlink;

import static org.assertj.core.api.Assertions.assertThat;

import africa.tesa.bloodlink.support.AbstractPostgresIT;
import java.net.http.HttpResponse;
import java.util.List;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.jdbc.core.simple.JdbcClient;

/**
 * The brief's definition of done for seed data, checked on every build against the demo data
 * (005-demo-data.sql, generated by scripts/gen_seed.py). Only seed rows are counted: unit references start with SEED-,
 * requests have payload_hash 'seed', so data other tests add does not change the answer.
 */
class SeedDataIT extends AbstractPostgresIT {

    private static final String SEED_UNITS = "reference LIKE 'SEED-%'";
    private static final String SEED_REQUESTS = "payload_hash = 'seed'";

    @Autowired
    JdbcClient jdbc;

    @Test
    void atLeastSixtyUnitsAcrossAllEightGroupsAtEachOfThreeBanks() {
        int units = count("SELECT count(*) FROM unit WHERE " + SEED_UNITS);
        List<Integer> groupsPerBank = jdbc.sql("SELECT count(DISTINCT blood_group || rhesus)::int FROM unit WHERE "
                + SEED_UNITS + " GROUP BY bank_id")
            .query(Integer.class).list();

        assertThat(units).isGreaterThanOrEqualTo(60);
        assertThat(groupsPerBank).hasSize(3).containsOnly(8);
    }

    @Test
    void unitsCoverEveryState() {
        List<String> shown = jdbc.sql("SELECT DISTINCT effective_state FROM unit_status WHERE " + SEED_UNITS)
            .query(String.class).list();

        assertThat(shown).containsExactlyInAnyOrder("AVAILABLE", "RESERVED", "ISSUED", "EXPIRED", "DISCARDED");
    }

    @Test
    void atLeastTwentyRequestsCoveringEveryState() {
        int requests = count("SELECT count(*) FROM blood_request WHERE " + SEED_REQUESTS);
        List<String> shown = jdbc.sql("SELECT DISTINCT effective_state FROM blood_request_status WHERE " + SEED_REQUESTS)
            .query(String.class).list();

        assertThat(requests).isGreaterThanOrEqualTo(20);
        assertThat(shown).containsExactlyInAnyOrder(
            "PENDING", "APPROVED", "DECLINED", "CANCELLED", "FULFILLED", "LAPSED", "UNIT_EXPIRED");
    }

    @Test
    void twoUnitsExpiredWhileReservedAndEachReachedItsFinalState() {
        List<String> finalStates = jdbc.sql("""
                SELECT u.effective_state || '/' || r.effective_status || '/' || br.effective_state
                  FROM reservation_status r
                  JOIN unit_status u ON u.id = r.unit_id
                  JOIN blood_request_status br ON br.id = r.request_id
                 WHERE r.status = 'UNIT_EXPIRED' AND br.payload_hash = 'seed'""")
            .query(String.class).list();

        // Unit EXPIRED, reservation UNIT_EXPIRED, request UNIT_EXPIRED: the request shows what happened.
        assertThat(finalStates).hasSize(2).containsOnly("EXPIRED/UNIT_EXPIRED/UNIT_EXPIRED");
    }

    @Test
    void eachExpiredWhileReservedRequestSaysWhatHappenedInItsHistory() throws Exception {
        List<String> ids = jdbc.sql("SELECT id::text FROM blood_request WHERE state = 'UNIT_EXPIRED' AND " + SEED_REQUESTS)
            .query(String.class).list();
        String admin = signIn(ADMIN);

        for (String id : ids) {
            HttpResponse<String> response = get("/requests/" + id, admin);
            List<String> events = json(response.body(), "$.history[*].event");
            assertThat(events).as(id).contains("CREATED", "APPROVED", "UNIT_EXPIRED");
            assertThat((String) json(response.body(), "$.state")).isEqualTo("UNIT_EXPIRED");
        }
    }

    @Test
    void aUnitPastExpiryThatNoJobHasMarkedIsStillShownAsExpired() {
        List<String> shown = jdbc.sql("""
                SELECT effective_state FROM unit_status
                 WHERE reference LIKE 'SEED-%' AND state = 'AVAILABLE' AND expiry_date < current_date""")
            .query(String.class).list();

        assertThat(shown).isNotEmpty().containsOnly("EXPIRED");
    }

    @Test
    void theRaceIsReadyToDemonstrateThreePendingRequestsForLagosLastONegativeUnit() {
        int seededLastUnit = count("""
                SELECT count(*) FROM unit_status
                 WHERE reference LIKE 'SEED-%' AND bank_id = '0d1f6a3e-2b4c-4e5f-8a9b-1c2d3e4f5a6b'
                   AND blood_group = 'O' AND rhesus = 'NEGATIVE' AND component = 'RED_CELLS' AND effective_state = 'AVAILABLE'""");
        int hospitalsWaiting = count("""
                SELECT count(DISTINCT hospital_id) FROM blood_request
                 WHERE payload_hash = 'seed' AND state = 'PENDING' AND bank_id = '0d1f6a3e-2b4c-4e5f-8a9b-1c2d3e4f5a6b'
                   AND blood_group = 'O' AND rhesus = 'NEGATIVE' AND component = 'RED_CELLS'""");

        assertThat(seededLastUnit).isEqualTo(1);
        assertThat(hospitalsWaiting).isEqualTo(3);
    }

    @Test
    void everyDeclinedRequestHasItsReason() {
        int withoutReason = count("SELECT count(*) FROM blood_request WHERE state = 'DECLINED' AND decline_reason IS NULL AND "
            + SEED_REQUESTS);

        assertThat(withoutReason).isZero();
    }

    @Test
    void everyDemoBankHasDonationSlotsOnEachOfTheNextFourteenDays() {
        // 008-demo-slots.sql tops these up on every deploy, so the demo never runs out of future slots.
        int bankDays = count("""
                SELECT count(DISTINCT (bank_id, (starts_at AT TIME ZONE 'Africa/Lagos')::date))::int FROM donation_slot
                 WHERE payload_hash = 'seed'
                   AND (starts_at AT TIME ZONE 'Africa/Lagos')::date
                       BETWEEN (now() AT TIME ZONE 'Africa/Lagos')::date + 1 AND (now() AT TIME ZONE 'Africa/Lagos')::date + 14""");

        assertThat(bankDays).isEqualTo(3 * 14);
    }

    private int count(String sql) {
        return jdbc.sql(sql).query(Integer.class).single();
    }
}
